import { readFileSync } from 'node:fs'
import { defineLoader } from 'vitepress'

export interface ToolParam {
  name: string
  type: string
  required: boolean
  default: unknown
  description: string
}

export interface Tool {
  name: string
  category: string
  page: string
  url: string
  signature: string
  returns: string
  summary: string
  details: string
  params: ToolParam[]
}

export interface ToolCatalog {
  count: number
  tools: Tool[]
}

declare const data: ToolCatalog
export { data }

// Generated by scripts/gen_tools_json.py from the registered MCP tools.
export default defineLoader({
  watch: ['../../public/tools.json'],
  load(files: string[]): ToolCatalog {
    return JSON.parse(readFileSync(files[0], 'utf-8'))
  },
})
